// Texts, Google Sheet column names and node names used below. Edit the texts here.
const T = {
  "locale": "en-US",
  "nodes": {
    "config": "Config",
    "leadWebhook": "Receive lead (webhook)"
  },
  "cols": {
    "lead": {
      "id": "Lead ID",
      "lastEnquiry": "Last Enquiry At",
      "name": "Name",
      "email": "Email",
      "phone": "Phone",
      "intent": "Intent",
      "propertyRef": "Property Ref",
      "budget": "Budget",
      "timeline": "Timeline",
      "areas": "Preferred Areas",
      "minBeds": "Min Bedrooms",
      "propertyType": "Property Type",
      "message": "Message",
      "source": "Source",
      "score": "Score",
      "temperature": "Temperature",
      "status": "Status",
      "step": "Follow-up Step",
      "lastContact": "Last Contact At",
      "nextFollowUp": "Next Follow-up At",
      "notes": "Notes"
    }
  },
  "values": {
    "intent": {
      "buy": "buy",
      "sell": "sell",
      "rent": "rent",
      "other": "other"
    },
    "timeline": {
      "soon": "0-3 months",
      "mid": "3-6 months",
      "later": "6+ months",
      "unknown": "unknown"
    },
    "temp": {
      "hot": "Hot",
      "warm": "Warm",
      "cold": "Cold"
    },
    "leadStatus": {
      "new": "New",
      "contacted": "Contacted"
    },
    "listingStatus": {
      "available": "Available"
    },
    "listingType": {
      "sale": "Sale",
      "rent": "Rent"
    },
    "viewingStatus": {
      "booked": "Booked",
      "done": "Done",
      "cancelled": "Cancelled"
    }
  },
  "text": {
    "lead": {
      "errors": {
        "required": "An email address or a phone number is required.",
        "invalidEmail": "The email address looks invalid."
      },
      "defaultSource": "Website form",
      "refText": " about {ref}",
      "refDash": " — {ref}",
      "greeting": "<p>Hi {firstName},</p>",
      "greetingNoName": "<p>Hi there,</p>",
      "subjects": {
        "buy": "Your property enquiry{refDash}",
        "sell": "Your free property valuation",
        "rent": "Your rental enquiry{refDash}",
        "other": "Thanks for contacting {agency}"
      },
      "bodies": {
        "buy": "<p>Thanks for your enquiry{refText}. I'd be happy to arrange a viewing — you can pick a time here: {booking}.</p>\n<p>To send you the most relevant homes, could you reply with: your maximum budget, whether you have a mortgage in principle, and when you'd like to move?</p>",
        "sell": "<p>Thanks for getting in touch about selling. I'd love to give you a free, no-obligation valuation — book a time that suits you: {booking}.</p>\n<p>If you reply with the address and a few details about the property, I'll prepare comparable sales before we meet.</p>",
        "rent": "<p>Thanks for your rental enquiry{refText}. You can book a viewing here: {booking}.</p>\n<p>To speed things up, let me know your move-in date, how many people will live in the property and whether you have pets.</p>",
        "other": "<p>Thanks for your message{refText}. I'll get back to you shortly — or book a call at a time that suits you: {booking}.</p>"
      },
      "signature": "<p>Best regards,<br>{agentName}<br>{agency} · {agentPhone}</p>",
      "alertSubject": "🔥 Hot {intent} lead: {who} (score {score})",
      "alertHtml": "<p><b>{name}</b> — {email} — {phone}</p>\n<p>Intent: {intent} · Budget: {budget} · Timeline: {timeline} · Ref: {ref}</p>\n<p>Message: {message}</p><p>Call them now — leads contacted within 5 minutes convert far better.</p>",
      "unknown": "Unknown",
      "price": "{currency}{amount}"
    }
  }
};

// Normalize the incoming enquiry, validate it, score it and prepare the emails.
// Accepts flat JSON or form-encoded fields (English or French field names) from any form, portal parser or webhook.
// Helpers (texts and column names live in the T object above — edit them there).
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fill = (tpl, vars) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
const greet = (tpl, name) => (String(name || '').trim()
  ? fill(tpl.greeting, { firstName: esc(String(name).trim().split(' ')[0]) })
  : tpl.greetingNoName);
// Internal key from a cell value: accepts the key itself ("buy") or the label of this language ("Buy", "achat").
const keyOf = (map, label) => {
  const l = String(label ?? '').trim().toLowerCase();
  for (const [k, v] of Object.entries(map)) if (l === k || l === String(v).toLowerCase()) return k;
  return null;
};
const money = (n) => new Intl.NumberFormat(T.locale, { maximumFractionDigits: 0 }).format(n);
const isEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(v || '').trim());
const config = $(T.nodes.config).first().json;
const raw = $(T.nodes.leadWebhook).first().json.body || {};
const C = T.cols.lead;
const V = T.values;
const X = T.text;

// Case-insensitive field lookup: first non-empty value among the aliases (accents and spaces ignored).
const norm = (k) => k.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[\s-]/g, '_');
const lower = {};
for (const [k, v] of Object.entries(raw)) lower[norm(k)] = v;
const pick = (...aliases) => {
  for (const a of aliases) {
    const v = lower[a];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

// --- Contact details ---------------------------------------------------------------
let name = pick('name', 'full_name', 'fullname', 'your_name', 'contact_name', 'nom_complet', 'nom_et_prenom');
if (!name) name = [pick('first_name', 'firstname', 'given_name', 'prenom'), pick('last_name', 'lastname', 'surname', 'nom')].filter(Boolean).join(' ');
const email = pick('email', 'e_mail', 'email_address', 'mail', 'courriel', 'adresse_email', 'adresse_e_mail').toLowerCase();
const phone = pick('phone', 'phone_number', 'telephone', 'tel', 'mobile', 'cell', 'portable').replace(/[^\d+]/g, '');
const message = pick('message', 'comments', 'comment', 'enquiry', 'inquiry', 'notes', 'details', 'commentaire', 'commentaires', 'demande');
const emailValid = isEmail(email);

// --- Intent: buy / sell / rent / other (English or French wording) ------------------------
// The explicit form field wins; the free-text message is only a fallback (stricter patterns).
const classify = (text, strict) => {
  const t = text.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  if (/\b(sell|selling|sale of my|valuation|value my|appraisal|list my|vendre|vente de mon|estimation|estimer|mettre en vente)\b/.test(t)) return 'sell';
  if (strict ? /\b(to rent|for rent|renting|to let|letting|lease|tenant|louer|location|locataire|bail)\b/.test(t)
             : /\b(rent|renting|let|letting|lease|tenant|rental|louer|location|locataire)\b/.test(t)) return 'rent';
  if (strict ? /\b(buy|buying|purchase|book a viewing|arrange a viewing|interested in (the|this|your)|acheter|achat|acquerir|visiter|une visite)\b/.test(t)
             : /\b(buy|buying|purchase|viewing|buyer|acheter|achat|acquerir|acquereur|visite)\b/.test(t)) return 'buy';
  return 'other';
};
const intentField = pick('intent', 'type', 'enquiry_type', 'inquiry_type', 'interest', 'reason', 'projet', 'type_de_demande', 'objet');
let intent = intentField ? classify(intentField, false) : 'other';
if (intent === 'other') intent = classify(message, true);

// --- Budget: "$450,000", "450k", "1.2M", "450 000 €" -> number ------------------------------
const parseMoney = (s) => {
  if (!s) return null;
  const m = String(s).toLowerCase().replace(/[\s,  ]/g, '').match(/(\d+(?:\.\d+)?)(k|m)?/);
  if (!m) return null;
  const n = parseFloat(m[1]) * (m[2] === 'm' ? 1e6 : m[2] === 'k' ? 1e3 : 1);
  return Number.isFinite(n) && n > 0 ? Math.round(n) : null;
};
const budget = parseMoney(pick('budget', 'max_budget', 'price', 'max_price', 'price_range', 'prix', 'budget_max'));

// --- Timeline --------------------------------------------------------------------------
const tl = pick('timeline', 'timeframe', 'move_date', 'when', 'moving', 'delai', 'date_emmenagement', 'quand')
  .toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
let timeline = 'unknown';
if (!tl || /not sure|unsure|don'?t know|undecided|ne sais pas|je ne sais|pas sur|indecis/.test(tl)) timeline = 'unknown';
else if (/\b(asap|immediate(ly)?|right away|now|this month|next month|urgent(ly)?|[0-2]\s*(-|to|a)\s*3 (months?|mois)|[1-3] (months?|mois)|within (a|one|two|three) months?|des que possible|rapidement|tout de suite|ce mois|le mois prochain|immediatement)\b/.test(tl)) timeline = '0-3 months';
else if (/\b(3\s*(-|to|a)\s*6 (months?|mois)|[4-6] (months|mois)|this year|cette annee|spring|summer|autumn|fall|winter|printemps|ete|automne|hiver|within six months)\b/.test(tl)) timeline = '3-6 months';
else timeline = '6+ months';
const timelineKey = { '0-3 months': 'soon', '3-6 months': 'mid', '6+ months': 'later', unknown: 'unknown' }[timeline];

const propertyRef = pick('property_ref', 'property_id', 'listing_ref', 'listing_id', 'listing', 'ref', 'reference', 'mls', 'reference_bien', 'ref_bien', 'bien');
const areas = pick('areas', 'preferred_areas', 'location', 'city', 'neighbourhood', 'neighborhood', 'secteur', 'secteurs', 'ville', 'quartier');
const minBedrooms = parseInt(pick('bedrooms', 'min_bedrooms', 'beds', 'chambres', 'nb_chambres'), 10) || '';
const propertyType = pick('property_type', 'home_type', 'type_de_bien', 'type_bien');
const source = pick('source', 'utm_source', 'portal', 'channel', 'canal', 'portail') || X.lead.defaultSource;

// --- Validation ------------------------------------------------------------------------
const errors = [];
if (!emailValid && !phone) errors.push(X.lead.errors.required);
if (email && !emailValid) errors.push(X.lead.errors.invalidEmail);
if (errors.length) return [{ json: { isValid: false, errors } }];

// --- Stable lead ID (FNV-1a hash of email or phone) so repeat enquiries update the same row ---
const key = emailValid ? email : phone;
let h = 0x811c9dc5;
for (const ch of key) { h ^= ch.charCodeAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
const leadId = 'L-' + h.toString(36).toUpperCase();

// --- Score 0-100 ------------------------------------------------------------------------
let score = 0;
if (phone) score += 25;
if (timelineKey === 'soon') score += 20; else if (timelineKey === 'mid') score += 10;
if (budget) score += 15;
if (propertyRef) score += 10;
if (intent === 'sell') score += 10;
if (message.length >= 40) score += 10;
if (/pre-?approved|mortgage (in principle|approved)|cash buyer|proof of funds|chain[- ]free|accord de principe|pret accorde|financement valide|sans condition suspensive|comptant/i.test(message.normalize('NFD').replace(/[̀-ͯ]/g, ''))) score += 10;
score = Math.min(score, 100);
const tempKey = score >= Number(config.hotScoreThreshold) ? 'hot' : score >= Number(config.warmScoreThreshold) ? 'warm' : 'cold';

// --- Instant reply email ----------------------------------------------------------------
const vars = {
  ref: esc(propertyRef),
  booking: `<a href="${esc(config.bookingLink)}">${esc(config.bookingLink)}</a>`,
  agency: esc(config.agencyName), agentName: esc(config.agentName), agentPhone: esc(config.agentPhone),
};
vars.refText = propertyRef ? fill(X.lead.refText, vars) : '';
vars.refDash = propertyRef ? fill(X.lead.refDash, { ref: propertyRef }) : '';
const subject = fill(X.lead.subjects[intent], { ...vars, refDash: vars.refDash, agency: config.agencyName });

const now = DateTime.now().toISO();
const lead = {};
lead[C.id] = leadId; lead[C.lastEnquiry] = now; lead[C.name] = name; lead[C.email] = emailValid ? email : '';
lead[C.phone] = phone; lead[C.intent] = V.intent[intent]; lead[C.propertyRef] = propertyRef; lead[C.budget] = budget ?? '';
lead[C.timeline] = V.timeline[timelineKey]; lead[C.areas] = areas; lead[C.minBeds] = minBedrooms;
lead[C.propertyType] = propertyType; lead[C.message] = message; lead[C.source] = source; lead[C.score] = score;
lead[C.temperature] = V.temp[tempKey]; lead[C.step] = 0; lead[C.lastContact] = emailValid ? now : '';

return [{
  json: {
    isValid: true,
    isHot: tempKey === 'hot',
    hasEmail: emailValid,
    leadId, score, temperature: V.temp[tempKey],
    lead,
    reply: { to: email, subject, html: greet(X.lead, name) + fill(X.lead.bodies[intent], vars) + fill(X.lead.signature, vars) },
    alert: {
      subject: fill(X.lead.alertSubject, { intent: V.intent[intent], who: name || email || phone, score }),
      html: fill(X.lead.alertHtml, {
        name: esc(name || X.lead.unknown), email: esc(email || '-'), phone: esc(phone || '-'), intent: V.intent[intent],
        budget: budget == null ? '-' : fill(X.lead.price, { currency: esc(config.currencySymbol || ''), amount: money(budget) }), timeline: V.timeline[timelineKey], ref: esc(propertyRef || '-'), message: esc(message || '-'),
      }),
    },
  },
}];
